WITH unpacked AS (SELECT id, log_ts, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, context['version'] AS version, SIZE(context) AS num_context FROM app_logs) SELECT id, log_ts, version, num_context, CUME_DIST() OVER (ORDER BY num_context DESC NULLS FIRST) AS num_context_cume_dist, CUME_DIST() OVER (ORDER BY duration_sec NULLS FIRST) AS duration_sec_cume_dist, ROW_NUMBER() OVER (ORDER BY duration_sec DESC, id) AS seq_no, ROW_NUMBER() OVER (ORDER BY num_context DESC, id) AS event_seq, AVG(num_context) OVER (ORDER BY num_context, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS num_context_avg_2_prior FROM unpacked;
